<script>

import HeaderSection from "@/components/HeaderSection.vue";
import StatisticsSection from "@/components/StatisticsSection.vue";
import FooterSection from "@/components/FooterSection.vue";

export default {

    name: "WhyUniteCore",

    components: {
        HeaderSection,
        StatisticsSection,
        FooterSection
    },

    mounted() {

        this.handleHashScroll();

    },

    methods: {

        handleHashScroll() {

            /*
             * IMPORTANT:
             * Vue Router is using createWebHashHistory().
             *
             * Therefore:
             * window.location.hash
             * can be "#/WhyUniteCore"
             *
             * That value cannot be passed directly to
             * document.querySelector().
             */

            const hash = window.location.hash;

            /*
             * If there is no hash, simply start at the top.
             */
            if (!hash) {

                window.scrollTo({
                    top: 0,
                    behavior: "auto"
                });

                return;
            }

            /*
             * Vue Router hash history gives values such as:
             *
             * #/WhyUniteCore
             *
             * We only want a section hash such as:
             *
             * #approach
             *
             * or:
             *
             * #journey
             *
             * If the hash starts with "#/" it is the router route,
             * not a page-section anchor.
             */

            if (hash.startsWith("#/")) {

                return;

            }

            /*
             * Remove the "#" before using getElementById().
             *
             * Example:
             * "#approach" -> "approach"
             */

            const targetId = hash.substring(1);

            if (!targetId) {

                return;

            }

            this.$nextTick(() => {

                const element = document.getElementById(targetId);

                if (!element) {

                    return;

                }

                setTimeout(() => {

                    const headerOffset = 90;

                    const elementPosition =
                        element.getBoundingClientRect().top +
                        window.pageYOffset;

                    const offsetPosition =
                        elementPosition - headerOffset;

                    window.scrollTo({

                        top: offsetPosition,

                        behavior: "smooth"

                    });

                }, 100);

            });

        }

    }

};

</script>



