    margin: 22px 0 25px;

    font-size: clamp(52px, 6.5vw, 88px);
    line-height: .92;
    letter-spacing: -.055em;
    font-weight: 800;
}

.hero-content h1 span {
    display: block;
    color: #f5820b;
}

.hero-description {
    max-width: 590px;
    margin: 0;

    color: rgba(255, 255, 255, .72);

    font-size: 17px;
    line-height: 1.8;
}

.hero-actions {
    display: flex;
    align-items: center;
    gap: 14px;

    margin-top: 35px;
}

.hero-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 12px;

    min-height: 52px;

    padding: 0 22px;

    border-radius: 5px;

    text-decoration: none;

    font-size: 13px;
    font-weight: 800;

    transition:
        transform .25s ease,
        background .25s ease,
        color .25s ease,
        border-color .25s ease;
}

.hero-btn:hover {
    transform: translateY(-3px);
}

.hero-btn-primary {
    background: #f5820b;
    color: #111;
}

.hero-btn-primary:hover {
    background: #ff9f2f;
    color: #111;
}

.hero-btn-secondary {
    border: 1px solid rgba(255, 255, 255, .25);
    color: #ffffff;
}

.hero-btn-secondary:hover {
    border-color: #f5820b;
    color: #f5820b;
}

.hero-meta {
    display: flex;
    flex-wrap: wrap;

    gap: 35px;

    margin-top: 55px;
    padding-top: 25px;

    border-top: 1px solid rgba(255, 255, 255, .12);
}

.hero-meta-item {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.hero-meta-item strong {
    color: #ffffff;
    font-size: 27px;
    line-height: 1;
}

.hero-meta-item span {
    color: rgba(255, 255, 255, .48);

    font-size: 10px;
    letter-spacing: .06em;

    text-transform: uppercase;
}


/* ============================================================
   HERO VISUAL
============================================================ */

.hero-visual {
    position: relative;

    width: min(100%, 560px);

    aspect-ratio: 1;

    margin-left: auto;
}

.orbit {
    position: absolute;

    left: 50%;
    top: 50%;

    border: 1px solid rgba(245, 130, 11, .24);
    border-radius: 50%;

    transform: translate(-50%, -50%);
}

.orbit-one {
    width: 48%;
    height: 48%;
}

.orbit-two {
    width: 70%;
    height: 70%;

    border-color: rgba(245, 130, 11, .16);
}

.orbit-three {
    width: 92%;
    height: 92%;

    border-color: rgba(255, 255, 255, .09);
}

.core-circle {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 175px;
    height: 175px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    transform: translate(-50%, -50%);

    background:
        radial-gradient(circle,
            rgba(245, 130, 11, .5),
            rgba(245, 130, 11, .08) 55%,
            transparent 70%);

    box-shadow:
        0 0 80px rgba(245, 130, 11, .25),
        inset 0 0 40px rgba(245, 130, 11, .2);
}

.core-inner {
    width: 110px;
    height: 110px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(245, 130, 11, .5);

    border-radius: 50%;

    background: #102e27;

    box-shadow:
        0 0 35px rgba(245, 130, 11, .2);
}

.core-inner span {
    color: #f5820b;

    font-size: 30px;
    font-weight: 900;

    letter-spacing: -.05em;
}

.floating-card {
    position: absolute;

    display: flex;
    align-items: center;

    gap: 12px;

    min-width: 155px;

    padding: 13px 15px;

    border: 1px solid rgba(255, 255, 255, .1);

    border-radius: 10px;

    background: rgba(255, 255, 255, .06);

    backdrop-filter: blur(15px);

    box-shadow:
        0 20px 50px rgba(0, 0, 0, .22);

    animation:
        floatingCard 4s ease-in-out infinite;
}

.floating-card strong {
    display: block;

    color: #ffffff;

    font-size: 12px;
}

.floating-card span {
    display: block;

    margin-top: 3px;

    color: rgba(255, 255, 255, .45);

    font-size: 9px;
}

.card-icon {
    width: 36px;
    height: 36px;

    flex: 0 0 36px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: rgba(245, 130, 11, .12);

    color: #f5820b;
}

.card-one {
    top: 12%;
    left: 5%;
}

.card-two {
    top: 22%;
    right: 0;

    animation-delay: .7s;
}

.card-three {
    bottom: 20%;
    left: 0;

    animation-delay: 1.3s;
}

.card-four {
    bottom: 8%;
    right: 5%;

    animation-delay: 2s;
}

@keyframes floatingCard {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-9px);
    }
}


/* ============================================================
   APPROACH
============================================================ */

.approach-section {
    padding: 125px 0;
    background: #ffffff;
}

.approach-grid {
    display: grid;

    grid-template-columns: .85fr 1.15fr;

    gap: 80px;

    margin-top: 70px;
}

.approach-main {
    position: relative;

    padding: 40px;

    border-radius: 12px;

    background: #102e27;

    color: #ffffff;

    overflow: hidden;
}

.approach-main::after {
    content: "";

    position: absolute;

    width: 250px;
    height: 250px;

    right: -100px;
    bottom: -120px;

    border-radius: 50%;

    background: rgba(245, 130, 11, .2);

    filter: blur(30px);
}

.approach-number {
    color: #f5820b;

    font-size: 12px;
    font-weight: 900;
    letter-spacing: .1em;
}

.approach-main h3 {
    margin: 45px 0 20px;

    font-size: clamp(32px, 4vw, 52px);

    line-height: 1;

    letter-spacing: -.04em;
}

.approach-main h3 span {
    display: block;
    color: #f5820b;
}

.approach-main p {
    max-width: 470px;

    color: rgba(255, 255, 255, .62);

    font-size: 15px;
    line-height: 1.8;
}

.approach-line {
    width: 70px;
    height: 2px;

    margin-top: 45px;

    background: #f5820b;
}

.approach-cards {
    display: grid;

    grid-template-columns: repeat(2, 1fr);

    gap: 18px;
}

.approach-card {
    position: relative;

    padding: 30px;

    border: 1px solid #e8ecea;

    border-radius: 10px;

    background: #f8faf9;

    transition:
        transform .25s ease,
        border-color .25s ease,
        box-shadow .25s ease;
}

.approach-card:hover {
    transform: translateY(-7px);

    border-color: rgba(245, 130, 11, .4);

    box-shadow:
        0 20px 45px rgba(16, 46, 39, .08);
}

.card-number {
    position: absolute;

    top: 20px;
    right: 20px;

    color: #cbd4d0;

    font-size: 11px;
    font-weight: 800;
}

.approach-card>i {
    display: block;

    margin-bottom: 25px;

    color: #f5820b;

    font-size: 28px;
}

.approach-card h4 {
    margin: 0 0 10px;

    color: #102e27;

    font-size: 19px;
}

.approach-card p {
    margin: 0;

    color: #6a7671;

    font-size: 13px;
    line-height: 1.7;
}


/* ============================================================
   DIFFERENCE
============================================================ */

.difference-section {
    position: relative;

    padding: 125px 0;

    overflow: hidden;

    background: #edf4f1;
}

.difference-bg {
    position: absolute;

    width: 500px;
    height: 500px;

    right: -200px;
    top: -200px;

    border-radius: 50%;

    background: rgba(245, 130, 11, .08);

    filter: blur(50px);
}

.difference-header {
    position: relative;

    z-index: 1;

    display: grid;

    grid-template-columns: 1fr .75fr;

    gap: 100px;

    align-items: end;
}

.difference-header p {
    margin: 0;
}

.difference-grid {
    position: relative;

    z-index: 1;

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 18px;

    margin-top: 65px;
}

.difference-item {
    padding: 35px 25px;

    border-top: 2px solid #d3ddd8;

    transition:
        transform .25s ease,
        border-color .25s ease;
}

.difference-item:hover {
    transform: translateY(-5px);

    border-color: #f5820b;
}

.difference-icon {
    width: 48px;
    height: 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 25px;

    border-radius: 50%;

    background: #ffffff;

    color: #f5820b;

    font-size: 20px;
}

.difference-item h3 {
    margin: 0 0 12px;

    color: #102e27;

    font-size: 19px;
}

.difference-item p {
    margin: 0;

    color: #68746f;

    font-size: 13px;

    line-height: 1.75;
}


/* ============================================================
   JOURNEY
============================================================ */

.journey-section {
    padding: 130px 0;

    background: #ffffff;
}

.journey-timeline {
    position: relative;

    max-width: 1000px;

    margin: 80px auto 0;
}

.timeline-line {
    position: absolute;

    top: 0;
    bottom: 0;

    left: 50%;

    width: 1px;

    background: #dce4e0;

    transform: translateX(-50%);
}

.timeline-item {
    position: relative;

    display: grid;

    grid-template-columns: 1fr 50px 1fr;

    align-items: center;

    min-height: 190px;
}

.timeline-year {
    padding-right: 50px;

    color: #f5820b;

    font-size: 24px;
    font-weight: 900;

    text-align: right;
}

.timeline-item.reverse .timeline-year {
    grid-column: 3;
    grid-row: 1;

    padding-right: 0;
    padding-left: 50px;

    text-align: left;
}

.timeline-dot {
    position: relative;

    z-index: 2;

    width: 14px;
    height: 14px;

    margin: auto;

    border: 3px solid #ffffff;

    border-radius: 50%;

    background: #f5820b;

    box-shadow:
        0 0 0 5px rgba(245, 130, 11, .12);
}

.timeline-content {
    padding-left: 50px;
}

.timeline-item.reverse .timeline-content {
    grid-column: 1;
    grid-row: 1;

    padding-left: 0;
    padding-right: 50px;

    text-align: right;
}

.timeline-content>span {
    color: #89948f;

    font-size: 9px;
    font-weight: 800;

    letter-spacing: .15em;
}

.timeline-content h3 {
    margin: 8px 0 10px;

    color: #102e27;

    font-size: 25px;
}

.timeline-content p {
    margin: 0;

    color: #6b7772;

    font-size: 13px;

    line-height: 1.7;
}

.timeline-stats {
    display: flex;

    gap: 25px;

    justify-content: flex-start;

    margin-top: 15px;
}

.timeline-item.reverse .timeline-stats {
    justify-content: flex-end;
}

.timeline-stats div {
    display: flex;
    flex-direction: column;
}

.timeline-stats strong {
    color: #f5820b;

    font-size: 21px;
}

.timeline-stats span {
    color: #7d8884;

    font-size: 10px;
}


/* ============================================================
   TEAM
============================================================ */

.team-section {
    padding: 125px 0;

    background: #102e27;

    color: #ffffff;
}

.team-grid {
    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 90px;

    align-items: center;
}

.team-content h2 {
    color: #ffffff;
}

.team-content p {
    max-width: 580px;

    color: rgba(255, 255, 255, .62);
}

.team-highlight {
    display: flex;
    align-items: center;

    gap: 18px;

    max-width: 500px;

    margin-top: 35px;
    padding: 20px;

    border-left: 2px solid #f5820b;

    background: rgba(255, 255, 255, .04);
}

.team-highlight>i {
    color: #f5820b;

    font-size: 26px;
}

.team-highlight strong,
.team-highlight span {
    display: block;
}

.team-highlight strong {
    margin-bottom: 5px;

    color: #ffffff;

    font-size: 14px;
}

.team-highlight span {
    color: rgba(255, 255, 255, .5);

    font-size: 12px;

    line-height: 1.5;
}

.team-visual {
    position: relative;

    width: min(100%, 500px);

    aspect-ratio: 1;

    margin: auto;
}

.team-circle {
    position: absolute;

    left: 50%;
    top: 50%;

    border: 1px solid rgba(245, 130, 11, .2);

    border-radius: 50%;

    transform: translate(-50%, -50%);
}

.team-circle-one {
    width: 65%;
    height: 65%;
}

.team-circle-two {
    width: 90%;
    height: 90%;
}

.team-center {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 115px;
    height: 115px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(245, 130, 11, .5);

    border-radius: 50%;

    transform: translate(-50%, -50%);

    background: rgba(245, 130, 11, .08);

    color: #f5820b;

    font-size: 38px;
}

.team-node {
    position: absolute;

    width: 55px;
    height: 55px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 255, 255, .12);

    border-radius: 50%;

    background: rgba(255, 255, 255, .05);

    color: #f5820b;

    font-size: 18px;
}

.node-one {
    left: 20%;
    top: 23%;
}

.node-two {
    right: 18%;
    top: 25%;
}

.node-three {
    left: 17%;
    bottom: 24%;
}

.node-four {
    right: 17%;
    bottom: 23%;
}


/* ============================================================
   PROCESS
============================================================ */

.process-section {
    padding: 125px 0;

    background: #ffffff;
}

.process-grid {
    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 18px;

    margin-top: 70px;
}

.process-card {
    position: relative;

    min-height: 310px;

    padding: 35px 28px;

    border: 1px solid #e7ece9;

    border-radius: 10px;

    background: #ffffff;

    transition:
        transform .25s ease,
        box-shadow .25s ease,
        border-color .25s ease;
}

.process-card:hover {
    transform: translateY(-7px);

    border-color: rgba(245, 130, 11, .4);

    box-shadow:
        0 25px 55px rgba(16, 46, 39, .08);
}

.process-number {
    position: absolute;

    top: 22px;
    right: 22px;

    color: #cbd4d0;

    font-size: 11px;
    font-weight: 900;
}

.process-card>i {
    display: block;

    margin-top: 35px;
    margin-bottom: 28px;

    color: #f5820b;

    font-size: 30px;
}

.process-card h3 {
    margin: 0 0 12px;

    color: #102e27;

    font-size: 20px;
}

.process-card p {
    margin: 0;

    color: #6d7874;

    font-size: 13px;

    line-height: 1.75;
}


/* ============================================================
   ECOSYSTEM
============================================================ */

.ecosystem-section {
    position: relative;

    padding: 130px 0;

    overflow: hidden;

    background: #edf4f1;
}

.ecosystem-glow {
    position: absolute;

    width: 600px;
    height: 600px;

    right: -200px;
    top: 50%;

    border-radius: 50%;

    transform: translateY(-50%);

    background: rgba(245, 130, 11, .08);

    filter: blur(70px);
}

.ecosystem-grid {
    position: relative;

    z-index: 1;

    display: grid;

    grid-template-columns: .9fr 1.1fr;

    gap: 70px;

    align-items: center;
}

.ecosystem-tags {
    display: flex;

    flex-wrap: wrap;

    gap: 8px;

    margin-top: 30px;
}

.ecosystem-tags span {
    padding: 9px 13px;

    border: 1px solid #d5dfda;

    border-radius: 4px;

    background: rgba(255, 255, 255, .6);

    color: #52615b;

    font-size: 10px;
    font-weight: 700;
}

.ecosystem-visual {
    position: relative;

    width: min(100%, 560px);

    aspect-ratio: 1;

    margin: auto;
}

.eco-core {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 135px;
    height: 135px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    border: 2px solid #f5820b;

    border-radius: 50%;

    transform: translate(-50%, -50%);

    background: #102e27;

    box-shadow:
        0 0 60px rgba(245, 130, 11, .2);
}

.eco-core span {
    color: rgba(255, 255, 255, .6);

    font-size: 9px;

    letter-spacing: .2em;
}

.eco-core strong {
    color: #f5820b;

    font-size: 25px;
}

.eco-node {
    position: absolute;

    z-index: 3;

    width: 75px;
    height: 75px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 5px;

    border: 1px solid rgba(16, 46, 39, .12);

    border-radius: 50%;

    background: #ffffff;

    color: #102e27;

    box-shadow:
        0 15px 35px rgba(16, 46, 39, .08);
}

.eco-node i {
    color: #f5820b;

    font-size: 18px;
}

.eco-node span {
    font-size: 8px;

    font-weight: 800;
}

.eco-one {
    left: 43%;
    top: 1%;
}

.eco-two {
    right: 8%;
    top: 22%;
}

.eco-three {
    right: 5%;
    bottom: 20%;
}

.eco-four {
    left: 42%;
    bottom: 1%;
}

.eco-five {
    left: 6%;
    bottom: 20%;
}

.eco-six {
    left: 5%;
    top: 22%;
}

.eco-line {
    position: absolute;

    left: 50%;
    top: 50%;

    width: 43%;
    height: 1px;

    transform-origin: left center;

    background: rgba(245, 130, 11, .25);
}

.eco-line-one {
    transform: rotate(-90deg);
}

.eco-line-two {
    transform: rotate(-30deg);
}

.eco-line-three {
    transform: rotate(30deg);
}

.eco-line-four {
    transform: rotate(90deg);
}

.eco-line-five {
    transform: rotate(150deg);
}

.eco-line-six {
    transform: rotate(210deg);
}


/* ============================================================
   STATISTICS
============================================================ */

.why-statistics {
    position: relative;

    background: #ffffff;

    overflow: hidden;
}


/* ============================================================
   FINAL CTA
============================================================ */

.final-cta {
    position: relative;

    overflow: hidden;

    padding: 110px 0;

    background: #102e27;

    color: #ffffff;
}

.final-cta-grid {
    position: absolute;

    inset: 0;

    opacity: .12;

    background-image:
        linear-gradient(rgba(255, 255, 255, .08) 1px,
            transparent 1px),
        linear-gradient(90deg,
            rgba(255, 255, 255, .08) 1px,
            transparent 1px);

    background-size: 55px 55px;
}

.final-cta-glow {
    position: absolute;

    width: 500px;
    height: 500px;

    right: -100px;
    top: -250px;

    border-radius: 50%;

    background: rgba(245, 130, 11, .16);

    filter: blur(60px);
}

.final-cta-content {
    position: relative;

    z-index: 2;

    max-width: 850px;
}

.final-cta-content h2 {
    margin: 18px 0;

    font-size: clamp(40px, 6vw, 75px);

    line-height: .95;

    letter-spacing: -.05em;
}

.final-cta-content h2 span {
    display: block;

    color: #f5820b;
}

.final-cta-content p {
    max-width: 600px;

    color: rgba(255, 255, 255, .62);

    font-size: 16px;

    line-height: 1.8;
}

.cta-button {
    display: inline-flex;

    align-items: center;

    gap: 13px;

    margin-top: 25px;

    padding: 15px 22px;

    border-radius: 5px;

    background: #f5820b;

    color: #111111;

    text-decoration: none;

    font-size: 13px;

    font-weight: 800;

    transition:
        transform .25s ease,
        background .25s ease;
}

.cta-button:hover {
    transform: translateY(-3px);

    background: #ff9f2f;

    color: #111111;
}


/* ============================================================
   TABLET
============================================================ */

@media (max-width: 1100px) {

    .why-hero .why-container {
        gap: 35px;
    }

    .difference-grid,
    .process-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .difference-header {
        gap: 50px;
    }

    .approach-grid,
    .ecosystem-grid {
        gap: 45px;
    }

}


/* ============================================================
   TABLET / SMALL LAPTOP
============================================================ */

@media (max-width: 900px) {

    .why-container {
        width: calc(100% - 35px);
    }

    .why-hero {
        min-height: auto;
    }

    .why-hero .why-container {
        grid-template-columns: 1fr;

        padding-top: 150px;
        padding-bottom: 80px;
    }

    .hero-content {
        max-width: 720px;
    }

    /*
       IMPORTANT:
       Do NOT use transform: scale() here.
       The visual needs to remain responsive naturally.
    */
    .hero-visual {
        width: min(100%, 520px);

        aspect-ratio: 1;

        margin: 20px auto 0;
    }

    .approach-grid,
    .team-grid,
    .ecosystem-grid,
    .difference-header {
        grid-template-columns: 1fr;
    }

    .difference-header {
        gap: 20px;
    }

    .timeline-item {
        grid-template-columns: 70px 35px 1fr;

        min-height: 180px;
    }

    .timeline-year {
        padding-right: 10px;

        font-size: 17px;
    }

    .timeline-item.reverse .timeline-year {
        grid-column: 1;
        grid-row: 1;

        padding-left: 0;
